(65, 'Loa Bluetooth Marshall Stanmore III 80W Chính Hãng', 'marshall-stanmore-iii', 4, 'Âm thanh', 11, 'Marshall', 8990000, 9990000, 15, 4.95, 76, 1250, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1545454675-3531b543be5d?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Bộ khuếch tán âm Class D 80W (Woofer 50W + 2 Tweeter 15W)', 'Thiết kế da sần Vintage & Núm kim loại đồng thau', 'Nguồn điện trực tiếp 100-240V', 'Bluetooth 5.2 LE Audio + Cổng AUX 3.5mm/RCA', 'Biểu tượng loa để bàn Marshall Stanmore III không gian âm trường mở rộng, bass nội lực uy lực và ngoại hình cổ điển đậm chất rock.', 1, '2026-06-30 00:00:00'),
(66, 'Loa Bluetooth Marshall Emberton II Kháng Nước IP67', 'marshall-emberton-ii', 4, 'Âm thanh', 11, 'Marshall', 3990000, 4590000, 25, 4.91, 64, 890, 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Âm thanh đa hướng True Stereophonic 360 độ', '2 củ loa toàn dải 2 inch 10W + 2 màng cộng hưởng thụ động', 'Pin khủng 30 giờ, Sạc nhanh 20 phút nghe 4 giờ', 'Chuẩn chống bụi nước IP67 siêu bền', 'Loa di động Marshall Emberton II âm thanh 360 độ True Stereophonic đặc trưng, pin 30 giờ và tính năng Stack Mode kết nối nhiều loa cùng lúc.', 0, '2026-05-15 00:00:00'),
(67, 'Loa Bluetooth JBL Charge 5 Công Suất 40W Pin 20h', 'jbl-charge-5', 4, 'Âm thanh', 12, 'JBL', 3490000, 3990000, 30, 4.88, 105, 1320, 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'JBL Original Pro Sound công nghệ Bass Radiator kép', 'Racetrack driver 52x90mm + Tweeter 20mm riêng biệt', 'Pin 7500 mAh chơi nhạc 20 giờ kiêm sạc dự phòng điện thoại', 'Kháng nước chống bụi IP67 chuẩn dã ngoại', 'Loa di động tiệc tùng JBL Charge 5 chất âm JBL Pro Sound bùng nổ, thời lượng pin 20 giờ và khả năng sạc ngược cho smartphone.', 1, '2026-07-18 00:00:00'),
(68, 'Loa Bluetooth JBL Flip 6 Nhỏ Gọn Kháng Nước', 'jbl-flip-6', 4, 'Âm thanh', 12, 'JBL', 2490000, 2990000, 35, 4.85, 82, 1020, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1545454675-3531b543be5d?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Hệ thống loa 2 chiều 30W (Woofer 20W + Tweeter 10W)', 'Màng loa hình đường đua + 2 màng thụ động tối ưu bass', 'Pin 12 giờ, Sạc Type-C bảo vệ an toàn', 'Kháng nước và chống bụi hoàn hảo IP67', 'JBL Flip 6 thiết kế hình ống năng động cầm vừa vặn, âm thanh 2 chiều trong trẻo và công nghệ PartyBoost ghép nối nhiều loa.', 0, '2026-06-05 00:00:00'),
(69, 'Tai nghe Sony ULT WEAR Chống Ồn Bass Siêu Trầm', 'sony-ult-wear', 4, 'Âm thanh', 5, 'Sony', 3990000, 4490000, 25, 4.84, 47, 760, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Sony Integrated Processor V1 tối ưu chống ồn', 'Củ loa 40mm chuyên biệt dòng ULT Power Sound', 'Pin 30 giờ (bật ANC), Sạc nhanh 3 phút nghe 90 phút', 'Nút bấm ULT kích hoạt 2 chế độ Extra Bass uy lực', 'Sony ULT WEAR sinh ra cho tín đồ nhạc sôi động EDM/Hip-hop với nút bấm ULT tăng cường âm trầm rung chuyển màng nhĩ và chống ồn V1 xuất sắc.', 0, '2026-05-22 00:00:00'),
(70, 'Tai nghe Soundcore Liberty 4 NC Chống Ồn 98.5%', 'soundcore-liberty-4-nc', 4, 'Âm thanh', 7, 'Anker', 1890000, 2390000, 45, 4.87, 118, 1420, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Chuẩn Hi-Res Wireless Audio với codec LDAC', 'Driver 11mm tùy chỉnh âm học độ nhạy cao', 'Pin 10 giờ (50 giờ kèm hộp), Sạc không dây Qi', 'Chống ồn thích ứng Adaptive ANC 2.0 giảm 98.5% tạp âm', 'Tai nghe Soundcore Liberty 4 NC chống ồn thích ứng chuẩn SGS giảm đến 98.5% tiếng ồn, chứng nhận âm thanh Hi-Res Wireless LDAC đỉnh cao.', 0, '2026-06-18 00:00:00'),
(71, 'Loa Bluetooth Soundcore Motion X600 Spatial Audio 50W', 'soundcore-motion-x600', 4, 'Âm thanh', 7, 'Anker', 3890000, 4590000, 20, 4.9, 52, 810, 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1545454675-3531b543be5d?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Thuật toán âm thanh không gian Spatial Audio 5 kênh', '5 củ loa và 3 bộ khuếch đại độc lập công suất 50W', 'Pin 6400 mAh nghe nhạc 12 giờ', 'Vỏ nhôm phay xước cao cấp chuẩn kháng nước IPX7', 'Loa di động Anker Soundcore Motion X600 mang lại trải nghiệm âm thanh rạp hát tại gia với công nghệ Spatial Audio 5 driver và chuẩn Hi-Res LDAC.', 0, '2026-07-25 00:00:00'),
(72, 'Apple Watch Series 10 GPS 46mm Nhôm Jet Black', 'apple-watch-series-10-46mm', 5, 'Smartwatch', 1, 'Apple', 11490000, 12290000, 25, 4.93, 62, 1350, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=800&auto=format&fit=crop&q=80"]', NULL, '64GB', 'Apple S10 SiP 64-bit lõi tứ Neural Engine', 'OLED góc nhìn rộng sáng hơn 40% khi nhìn nghiêng', 'Pin 18 giờ, Sạc siêu nhanh 80% chỉ trong 30 phút', 'Cảm biến độ sâu, nhiệt độ nước, phát hiện ngưng thở khi ngủ', 'Apple Watch Series 10 thiết kế mỏng nhất từ trước đến nay (9.7mm), màn hình hiển thị lớn hơn cả bản Ultra và sạc cực nhanh.', 1, '2026-09-28 00:00:00'),
(73, 'Apple Watch SE 2024 GPS 44mm Viền Nhôm', 'apple-watch-se-2024-44mm', 5, 'Smartwatch', 1, 'Apple', 6590000, 7490000, 35, 4.82, 95, 1280, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800&auto=format&fit=crop&q=80"]', NULL, '32GB', 'Apple S8 SiP 64-bit', 'Retina LTPO OLED 1000 nits kính Ion-X', 'Pin 18 giờ chế độ sử dụng tiêu chuẩn', 'Cảm biến nhịp tim quang học thế hệ 2 + Phát hiện té ngã', 'Apple Watch SE lựa chọn thông minh giá tốt nhất hệ sinh thái Apple, đầy đủ tính năng theo dõi vận động, nhịp tim và cứu hộ SOS.', 0, '2026-06-15 00:00:00'),
(74, 'Samsung Galaxy Watch7 44mm Bluetooth Kính Sapphire', 'samsung-galaxy-watch7-44mm', 5, 'Smartwatch', 2, 'Samsung', 7490000, 8490000, 22, 4.87, 51, 920, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=800&auto=format&fit=crop&q=80"]', '2GB', '32GB', 'Exynos W1000 tiến trình 3nm 5 nhân', '1.5 inch Super AMOLED 2000 nits Sapphire Glass', '425 mAh, Sạc nhanh không dây WPC', 'Cảm biến BioActive thế hệ mới + Huấn luyện viên giấc ngủ Galaxy AI', 'Galaxy Watch7 trang bị chip 3nm mạnh mẽ gấp 3 lần, định vị GPS tần số kép L1+L5 chuẩn xác từng mét và trợ lý sức khỏe Galaxy AI.', 1, '2026-08-05 00:00:00'),
(75, 'Samsung Galaxy Watch FE 40mm Dây Thể Thao', 'samsung-galaxy-watch-fe', 5, 'Smartwatch', 2, 'Samsung', 4490000, 4990000, 30, 4.79, 42, 780, 'https://images.unsplash.com/photo-1510017803434-a899398421b3?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1510017803434-a899398421b3?w=800&auto=format&fit=crop&q=80"]', '1.5GB', '16GB', 'Exynos W920 Dual-Core 1.18GHz', '1.2 inch Super AMOLED kính Sapphire chống trầy', '247 mAh, Sạc không dây từ tính', 'Cảm biến nhịp tim, đo nồng độ oxy trong máu SpO2, ECG', 'Galaxy Watch FE phiên bản Fan Edition tinh gọn, kính Sapphire cao cấp và hơn 100 chế độ tập luyện thể dục thể thao chuyên biệt.', 0, '2026-06-28 00:00:00'),
(76, 'Xiaomi Watch 2 Pro 4G LTE Snapdragon W5+ Gen 1', 'xiaomi-watch-2-pro', 5, 'Smartwatch', 3, 'Xiaomi', 5990000, 6990000, 18, 4.83, 39, 690, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=800&auto=format&fit=crop&q=80"]', '2GB', '32GB', 'Snapdragon W5+ Gen 1 4nm tiết kiệm điện', '1.43 inch AMOLED 466x466 600 nits khung thép không gỉ', '495 mAh, Thời lượng pin 55 giờ ở chế độ LTE', 'Hệ điều hành Google Wear OS đầy đủ kho ứng dụng Play Store', 'Xiaomi Watch 2 Pro kết nối eSIM 4G độc lập nghe gọi không cần điện thoại, Wear OS mượt mà và khung vỏ thép không gỉ sang trọng.', 0, '2026-07-10 00:00:00'),
(77, 'Củ sạc nhanh Anker 30W GaN 511 Nano 3 A2147', 'cu-sac-anker-30w-gan-nano-3', 6, 'Phụ kiện chính hãng', 7, 'Anker', 390000, 520000, 80, 4.94, 260, 2450, 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Chíp bán dẫn GaN III nhỏ hơn 70% củ sạc 30W thường', '1 cổng USB-C Power Delivery 3.0 & PPS 30W', 'ActiveShield 2.0 đo nhiệt độ 3 triệu lần/ngày', 'Sạc siêu tốc iPhone 16 từ 0-50% trong 25 phút', 'Củ sạc siêu tí hon Anker Nano 3 công suất 30W hỗ trợ sạc nhanh tối đa cho iPhone 16 Pro Max, iPad Air và MacBook Air.', 1, '2026-08-12 00:00:00'),
(78, 'Pin dự phòng Anker MagGo 10.000mAh Qi2 15W Màn Hình LED', 'pin-du-phong-anker-maggo-10000mah', 6, 'Phụ kiện chính hãng', 7, 'Anker', 1490000, 1890000, 40, 4.91, 145, 1680, 'https://images.unsplash.com/photo-1609592424109-dd9892f1b177?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1609592424109-dd9892f1b177?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Chuẩn sạc không dây thế hệ mới Qi2 Certified 15W', 'Màn hình thông minh hiển thị chính xác % pin và thời gian sạc', 'Dung lượng 10.000 mAh, Cổng Type-C vào/ra công suất 27W', 'Hút nam châm từ tính MagSafe cực mạnh kiêm chân dựng máy gập', 'Pin sạc từ tính Anker MagGo chuẩn Qi2 15W sạc nhanh không dây gấp đôi MagSafe thường, màn hình thông minh hiển thị thời gian pin còn lại.', 1, '2026-08-20 00:00:00'),
(79, 'Cáp sạc Anker Bio-Braided Type-C to Type-C 240W 1.8m', 'cap-sac-anker-type-c-240w', 6, 'Phụ kiện chính hãng', 7, 'Anker', 290000, 390000, 90, 4.89, 198, 1900, 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'E-Marker chip tích hợp kiểm soát dòng điện an toàn', 'Dây bọc dù sinh học uốn gập 20.000 lần không đứt gãy', 'Hỗ trợ công suất truyền tải điện Power Delivery tối đa 240W', 'Tương thích mọi thiết bị từ iPhone 16 đến MacBook Pro 16 inch', 'Dây cáp bọc dù thân thiện môi trường Anker Bio-Braided chịu tải đến 240W, sạc tốc độ tối đa cho mọi laptop và smartphone hiện đại.', 0, '2026-07-15 00:00:00'),
(80, 'Bàn phím cơ Logitech G PRO X TKL LIGHTSPEED Wireless', 'logitech-g-pro-x-tkl', 6, 'Phụ kiện chính hãng', 8, 'Logitech', 4190000, 4690000, 20, 4.95, 78, 940, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Công nghệ không dây Lightspeed độ trễ cực thấp 1ms', 'Đèn LED RGB LIGHTSYNC 16.8 triệu màu từng phím', 'Pin sạc USB-C dùng liên tục 50 giờ chơi game', 'Switch cơ học GX Brown Tactile độ phản hồi xúc giác hoàn hảo', 'Bàn phím cơ thi đấu Esports chuyên nghiệp Logitech G PRO X TKL thiết kế Tenkeyless nhỏ gọn, keycap PBT doubleshot bền bỉ và kết nối Lightspeed 1ms.', 0, '2026-08-01 00:00:00'),
(81, 'Chuột Gaming không dây Logitech G Pro X Superlight 2', 'logitech-g-pro-x-superlight-2', 6, 'Phụ kiện chính hãng', 8, 'Logitech', 3490000, 3990000, 25, 4.97, 130, 1550, 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Cảm biến HERO 2 độ phân giải 32.000 DPI, theo dõi 500+ IPS', 'Switch quang học - cơ học lai LIGHTFORCE phản xạ tức thì', 'Pin khủng 95 giờ sử dụng, cổng sạc USB-C hiện đại', 'Trọng lượng siêu nhẹ chỉ 60g không cần đục lỗ tổ ong', 'Huyền thoại chuột gaming FPS thế giới Superlight 2 với trọng lượng siêu nhẹ 60g, switch hybrid LIGHTFORCE và tần số lấy mẫu Polling Rate 4000Hz.', 1, '2026-08-18 00:00:00'),
(82, 'Bút cảm ứng Apple Pencil Pro Dành Cho iPad M4 / M2', 'apple-pencil-pro', 6, 'Phụ kiện chính hãng', 1, 'Apple', 3290000, 3490000, 40, 4.96, 115, 1380, 'https://images.unsplash.com/photo-1589739900243-4b52cd9b104e?w=600&auto=format&fit=crop&q=80', '["https://images.unsplash.com/photo-1589739900243-4b52cd9b104e?w=800&auto=format&fit=crop&q=80"]', NULL, NULL, 'Cảm biến con quay hồi chuyển Barrel Roll xoay thân bút', 'Cảm ứng lực bóp Squeeze mở bảng công cụ tức thì', 'Sạc không dây từ tính gắn cạnh iPad, hỗ trợ Find My', 'Phản hồi xúc giác Haptic Feedback rung phản hồi khi thao tác', 'Apple Pencil Pro đỉnh cao sáng tạo với thao tác bóp Squeeze, xoay thân bút đổi nét cọ Barrel Roll và tìm kiếm vị trí Find My tiện lợi.', 0, '2026-06-25 00:00:00');
