INSERT INTO `reviews` (`id`, `product_id`, `user_id`, `user_name`, `rating`, `comment`, `status`, `created_at`) VALUES
(1, 1, 2, 'Tuấn Kiệt', 5, 'iPhone 16 Pro Max máy cầm đầm tay, viền titan sa mạc cực kỳ sang trọng. Camera Control zoom mượt mà!', 'approved', '2026-09-15 10:00:00'),
(2, 1, 4, 'Nguyễn Hương Lan', 5, 'Đã mua bản 256GB tại TechStore, giao siêu nhanh trong 2h, đóng gói niêm phong chính hãng 100%.', 'approved', '2026-09-15 10:00:00'),
(3, 4, 5, 'Trần Minh Hoàng', 5, 'Galaxy S24 Ultra màn hình phẳng nhìn rất thích, Galaxy AI khoanh tròn tìm kiếm cực kỳ tiện cho công việc.', 'approved', '2026-09-15 10:00:00'),
(4, 11, 4, 'Nguyễn Hương Lan', 5, 'MacBook Pro 14 M3 Pro màu Space Black xuất sắc, bàn phím gõ êm, pin dùng 2 ngày không cần sạc.', 'approved', '2026-09-15 10:00:00'),
(5, 14, 6, 'Lê Nhật Quang', 5, 'Zephyrus G16 OLED 240Hz hiển thị đỉnh chóp! Chơi Cyberpunk 2077 max setting mượt mà với RTX 4070.', 'approved', '2026-09-15 10:00:00'),
(6, 21, 7, 'Phạm Phương Mai', 5, 'iPad Pro M4 mỏng nhẹ đến kinh ngạc, màn OLED đen sâu tuyệt đối, vẽ vời cực sướng.', 'approved', '2026-09-15 10:00:00'),
(7, 27, 2, 'Tuấn Kiệt', 5, 'Sony WH-1000XM5 đeo êm ái cách ly hoàn toàn tiếng ồn văn phòng. Âm bass trầm ấm chuẩn gu.', 'approved', '2026-09-15 10:00:00'),
(8, 30, 4, 'Nguyễn Hương Lan', 5, 'AirPods Pro 2 cổng Type-C tiện dụng, chống ồn tốt hơn bản cũ rất nhiều, âm thanh vòm sống động.', 'approved', '2026-09-15 10:00:00'),
(9, 41, 5, 'Trần Minh Hoàng', 5, 'Logitech MX Master 3S con lăn MagSpeed lướt vèo vèo qua nghìn dòng code Excel, click chuột êm ru không tiếng động.', 'approved', '2026-09-15 10:00:00'),
(10, 42, 6, 'Lê Nhật Quang', 5, 'Bàn phím cơ low profile gõ tactile rất đầm tay, kết nối Bluetooth với cả Mac và PC chuyển qua lại 1 chạm.', 'approved', '2026-09-15 10:00:00'),
(11, 39, 2, 'Tuấn Kiệt', 5, 'Củ sạc Anker GaN 65W nhỏ xíu mà sạc cùng lúc được cả laptop và iPhone, không hề bị nóng máy.', 'approved', '2026-09-15 10:00:00'),
(12, 35, 6, 'Lê Nhật Quang', 5, 'Apple Watch Ultra 2 màn hình 3000 nits ra nắng gắt xem rõ nét, pin dùng thoải mái 3 ngày leo núi.', 'approved', '2026-09-15 10:00:00'),
(13, 2, 7, 'Phạm Phương Mai', 5, 'iPhone 16 màu xanh Ultramarine ở ngoài đẹp hơn trên ảnh, máy gọn nhẹ chụp chân dung rất nét.', 'approved', '2026-09-15 10:00:00'),
(14, 7, 5, 'Trần Minh Hoàng', 5, 'Xiaomi 14 Ultra camera Leica tone màu vintage mê mẩn, xóa phông quang học chân thật không bị giả.', 'approved', '2026-09-15 10:00:00'),
(15, 15, 4, 'Nguyễn Hương Lan', 4, 'Zenbook 14 OLED mỏng nhẹ mang đi công tác rất tiện, màn hình đẹp nhưng hơi bám vân tay chút.', 'approved', '2026-09-15 10:00:00'),
(16, 22, 7, 'Phạm Phương Mai', 5, 'iPad Air 6 chip M2 chạy các app chỉnh video LumaFusion siêu nhanh, giá hợp lý hơn Pro nhiều.', 'approved', '2026-09-15 10:00:00'),
(17, 37, 5, 'Trần Minh Hoàng', 5, 'Galaxy Watch Ultra GPS bắt sóng rất nhạy, đo chỉ số sức khỏe chi tiết, pin trâu hơn hẳn các đời trước.', 'approved', '2026-09-15 10:00:00'),
(18, 9, 6, 'Lê Nhật Quang', 5, 'ROG Phone 8 Pro chiến Genshin Impact 60fps ổn định không drop, nút trigger bấm nhạy như tay cầm.', 'approved', '2026-09-15 10:00:00'),
(19, 40, 2, 'Tuấn Kiệt', 5, 'Sạc 100W Anker dùng cho MacBook 16 inch ngon lành, chân cắm chắc chắn không bị lỏng lẻo.', 'approved', '2026-09-15 10:00:00'),
(20, 28, 5, 'Trần Minh Hoàng', 4, 'WF-1000XM5 chống ồn tốt, âm thanh chi tiết nhưng nút đệm tai bọt biển cần đeo quen mới thấy êm.', 'approved', '2026-09-15 10:00:00'),
(21, 17, 4, 'Nguyễn Hương Lan', 5, 'Dell XPS 14 thiết kế kính tương lai quá đẹp, bàn phím và trackpad tàng hình độc lạ ấn tượng.', 'approved', '2026-09-15 10:00:00'),
(22, 33, 7, 'Phạm Phương Mai', 5, 'Redmi Buds 5 Pro giá hơn 1 triệu mà chống ồn và pin quá tốt, sinh viên dùng rất kinh tế.', 'approved', '2026-09-15 10:00:00'),
(23, 10, 5, 'Trần Minh Hoàng', 4, 'Galaxy A55 viền kim loại chắc chắn, màn hình 120Hz mượt, pin trâu dùng cả ngày.', 'approved', '2026-09-15 10:00:00'),
(24, 24, 6, 'Lê Nhật Quang', 5, 'Tab S9 Ultra màn 14.6 inch to như laptop, bút S-Pen viết ghi chú không có độ trễ.', 'approved', '2026-09-15 10:00:00'),
(25, 4, 2, 'Tuấn Kiệt', 5, 'Mua hàng bên TechStore nhân viên tư vấn nhiệt tình, quét VietQR thanh toán 3s là xong!', 'approved', '2026-09-15 10:00:00');
