(1, 1, 'admin@techstore.local', 'INITIALIZE_DATABASE', 'Khởi tạo hệ thống CSDL và bộ dữ liệu hạt giống 82 sản phẩm 12 thương hiệu 6 danh mục', '127.0.0.1', '2026-08-01 08:00:00'),
(2, 1, 'admin@techstore.local', 'CREATE_PRODUCT', 'Đăng tải sản phẩm mới iPhone 16 Pro Max 256GB lên hệ thống', '127.0.0.1', '2026-09-20 10:00:00'),
(3, 3, 'trung@techstore.local', 'UPDATE_ORDER_STATUS', 'Chuyển đơn TS-749201 sang completed và xác nhận tiền VietQR về tài khoản', '127.0.0.1', '2026-08-05 10:00:00'),
(4, 1, 'admin@techstore.local', 'CREATE_COUPON', 'Tạo chiến dịch mã giảm giá TECH10 giảm 10% tối đa 500k', '127.0.0.1', '2026-08-01 09:00:00'),
